request_examples.content:
{

  "Official_Account": "@TOA#_2C5SZEAEF",

  "Random": 9875,

  "MsgBody": [ // 消息体，由一个 element 数组组成，详见字段说明，五分钟包体相同认为是重复消息

      {

          "MsgType": "TIMTextElem", // 文本

          "MsgContent": {

              "Text": "red packet"

          }

      },

      {

          "MsgType": "TIMFaceElem", // 表情

          "MsgContent": {

              "Index": 6,

              "Data": "abc\\u0000\\u0001"

          }

      }

  ],

  "CloudCustomData": "your cloud custom data",

  "OfflinePushInfo": {

      "PushFlag": 0, // 正常推送，

      "Desc": "离线推送内容",

      "Ext": "这是透传的内容",

      "AndroidInfo": {

          "Sound": "android.mp3" // Android 系统通知铃声文件名，详情见“消息格式描述”。

      },

      "ApnsInfo": {

          "Sound": "apns.mp3", // iOS 系统通知铃声文件名，详情见“消息格式描述”。

          "BadgeMode": 1, // 这个字段缺省或者为0表示需要计数，为1表示本条消息不需要计数，即右上角图标数字不增加

          "Title":"apns title", // apns title

          "SubTitle":"apns subtitle", // apns subtitle

          "Image":"www.image.com" // image url

      }

  }

}

